from pathlib import Path
import json, re, sys

CID = "AUTO-DISCOVERY-54d13314c7879b58e46d"
MODEL_TASK = "A2Z-V4-ASTRA-POSTBUILD-20261006-R3-P2"
roots = [
    Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4",
    Path.home()/".local/share/prediction-project-executor/worktrees/DEV-PRED-A2Z-POSTBUILD-RETRY-20261006-E106",
    Path.home()/".local/state/prediction-codex-supervisor",
]
MAX = 2_000_000
seen = []
dicts = []

def walk(obj, path, parent=None):
    if isinstance(obj, dict):
        dicts.append((path, obj))
        for v in obj.values():
            walk(v, path, obj)
    elif isinstance(obj, list):
        for v in obj:
            walk(v, path, parent)

for root in roots:
    if not root.exists():
        continue
    for p in root.rglob("*"):
        try:
            if not p.is_file() or p.stat().st_size > MAX:
                continue
        except OSError:
            continue
        if p.suffix.lower() not in {".json", ".jsonl", ".log", ".txt"}:
            continue
        try:
            raw = p.read_text(errors="replace")
        except Exception:
            continue
        low = raw.lower()
        if MODEL_TASK.lower() not in low and CID.lower() not in low and "postbuild" not in low:
            continue
        seen.append(str(p))
        if p.suffix.lower() == ".json":
            try:
                walk(json.loads(raw), str(p))
            except Exception:
                pass
        elif p.suffix.lower() == ".jsonl":
            for line in raw.splitlines():
                try:
                    walk(json.loads(line), str(p))
                except Exception:
                    pass

def phase_is_post(d):
    vals = [d.get("phase"), d.get("review_phase"), d.get("gate"), d.get("review_kind")]
    return any(str(v).upper() == "POSTBUILD" or "POSTBUILD" in str(v).upper() for v in vals if v is not None)

def candidate_matches(d):
    c = d.get("candidate_id")
    if c is None:
        return True
    return c == CID

def task_matches(d):
    vals = [d.get("task_id"), d.get("source_task_id"), d.get("model_task_id"), d.get("review_task_id")]
    return MODEL_TASK in [str(v) for v in vals if v is not None]

def exact_model(d):
    return d.get("reviewer_model") == "GPT-6 Astra" and d.get("reviewer_model_slug") == "gpt-6-astra"

def binding_ok(d):
    b = d.get("binding_sha256")
    return isinstance(b, str) and re.fullmatch(r"[0-9a-f]{64}", b) is not None

# Candidate-state applied review is strongest evidence.
applied = []
for path,d in dicts:
    if d.get("candidate_id") != CID:
        continue
    reviews = d.get("astra_reviews")
    if not isinstance(reviews, dict):
        continue
    post = reviews.get("POSTBUILD")
    if isinstance(post, dict):
        applied.append((path, post, d))

# Direct POSTBUILD review/result records.
reviews = []
for path,d in dicts:
    dec = str(d.get("decision","")).upper()
    if dec not in {"APPROVE","NEEDS_REVISION","REVISE","REJECT","PARK"}:
        continue
    if not candidate_matches(d):
        continue
    if phase_is_post(d) or task_matches(d) or "postbuild" in path.lower():
        reviews.append((path,d))

def classify_record(d):
    dec = str(d.get("decision","")).upper()
    if dec == "APPROVE":
        if exact_model(d) and binding_ok(d):
            return "APPROVE_EXACT"
        return "APPROVE_UNVERIFIED"
    if dec in {"NEEDS_REVISION","REVISE"}:
        return "NEEDS_REVISION"
    if dec in {"REJECT","PARK"}:
        return dec
    return None

summary = {
    "candidate_id": CID,
    "model_task": MODEL_TASK,
    "files_seen": len(seen),
    "applied_postbuild_records": len(applied),
    "direct_review_records": len(reviews),
    "classification": "MISSING",
    "evidence_paths": []
}

# Prefer applied candidate-state review.
for path,post,state in applied:
    cls = classify_record(post)
    if cls:
        summary["classification"] = cls + "_APPLIED"
        summary["evidence_paths"] = [path]
        summary["queue_status"] = state.get("queue_status")
        summary["scientific_status"] = state.get("scientific_status")
        summary["review_ref"] = post.get("ref") or post.get("review_ref")
        print("E106_POSTBUILD_VERIFY "+json.dumps(summary,separators=(",",":")), flush=True)
        if cls == "APPROVE_EXACT":
            raise SystemExit(0)
        if cls == "NEEDS_REVISION":
            raise SystemExit(20)
        if cls in {"REJECT","PARK"}:
            raise SystemExit(21)
        raise SystemExit(24)

# Otherwise classify direct model/review records.
for path,d in reviews:
    cls = classify_record(d)
    if not cls:
        continue
    summary["classification"] = cls
    summary["evidence_paths"] = [path]
    summary["review_ref"] = d.get("ref") or d.get("review_ref")
    print("E106_POSTBUILD_VERIFY "+json.dumps(summary,separators=(",",":")), flush=True)
    if cls == "APPROVE_EXACT":
        raise SystemExit(0)
    if cls == "NEEDS_REVISION":
        raise SystemExit(20)
    if cls in {"REJECT","PARK"}:
        raise SystemExit(21)
    raise SystemExit(24)

print("E106_POSTBUILD_VERIFY "+json.dumps(summary,separators=(",",":")), flush=True)
raise SystemExit(23)
